mapper.select:
SELECT distinct td.id, td.code AS code, td.plan_transfer_date AS planTransferDate, td.instock_forecast_date AS instockForecastDate, td.upload_status AS uploadBatchStatus, td.delivery_logistics_supplier_name AS deliveryLogisticsSupplierName, td.transfer_logistics_supplier_name AS transferLogisticsSupplierName, td.transfer_channel_name AS transferChannelName, td.package_total_qty AS packageTotalQty, td.package_total_weight AS packageTotalWeight, td.instock_forecast_status AS instockForecastStatus, td.instock_forecast_remark AS instockForecastRemark, td.total_qty AS totalQty, td.create_user_name AS createUserName, td.create_time AS createTime, sb.platform_code as platformOrderCode FROM transfer_declare td LEFT JOIN transfer_declare_detail tdd ON tdd.main_id = td.id AND tdd.is_deleted = FALSE LEFT JOIN so_b2c sb on sb.id = tdd.so_id and sb.is_deleted = false WHERE td.is_deleted = FALSE
and ${params.sqlMap.default}
and ${params.sqlMap.detail}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
td.create_time desc

SELECT count(DISTINCT td.id) FROM transfer_declare td WHERE td.is_deleted = FALSE
and td.instock_forecast_status in
#{instockForecastStatus}

SELECT count(DISTINCT td.id) FROM transfer_declare td LEFT JOIN transfer_declare_detail tdd ON tdd.main_id = td.id AND tdd.is_deleted = FALSE WHERE td.is_deleted = FALSE
and tdd.transfer_status in
#{transferStatus}

SELECT td.id, tdd.id AS detailId, td.code AS code, td.plan_transfer_date AS planTransferDate, td.instock_forecast_date AS instockForecastDate, td.upload_status AS uploadBatchStatus, td.delivery_logistics_supplier_name AS deliveryLogisticsSupplierName, td.transfer_logistics_supplier_name AS transferLogisticsSupplierName, td.transfer_channel_name AS transferChannelName, td.package_total_qty AS packageTotalQty, td.package_total_weight AS packageTotalWeight, td.instock_forecast_status AS instockForecastStatus, td.instock_forecast_remark AS instockForecastRemark, tdd.so_code AS soCode, tdd.so_id AS soId, tdd.order_upload_status AS uploadOrderStatus, tdd.logistics_channel_name AS logisticsChannelName, tdd.track_no AS trackNo, tdd.outstock_status AS outstockStatus, tdd.transfer_status AS transferStatus, tdd.failure_reason AS failureReason, td.create_user_name AS createUserName, td.create_time AS createTime, sb.platform_code as platformOrderCode FROM transfer_declare_detail tdd INNER JOIN transfer_declare td ON tdd.main_id = td.id AND tdd.is_deleted = FALSE LEFT JOIN so_b2c sb on sb.id = tdd.so_id and sb.is_deleted = false WHERE td.is_deleted = FALSE
and ${params.sqlMap.default}
and ${params.sqlMap.detail}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
td.create_time desc
